#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const int MOD_A=998244353, MOD_B=1e9+7, BASE_VAL=1e6;
vector<int> array[7];
int prefix[7];
long long totalCount, currentOrder, totalAnswer;

void generate(int startVal, int level) {
    ++currentOrder;
    array[level].push_back((currentOrder - startVal + MOD_A) % MOD_A);
    (prefix[level] += array[level].back()) %= MOD_B;
    if (level == 6) return;
    for (int digit=0; digit<=9; ++digit) {
        generate(startVal*10 + digit, level+1);
    }
}

void traverse(long long x) {
    if (x > totalCount) return;
    if (x*BASE_VAL + BASE_VAL - 1 <= totalCount && x*BASE_VAL*10 > totalCount) {
        long long tempOrder = currentOrder;
        for (int i=0, factor=1; i<=6; ++i, factor*=10) {
            int size=array[i].size();
            int delta=((tempOrder - x*factor) % MOD_A + MOD_A) % MOD_A;
            int pos=lower_bound(array[i].begin(), array[i].end(), MOD_A - delta) - array[i].begin();
            totalAnswer = (totalAnswer + 1LL*delta*size + prefix[i]) % MOD_B;
            totalAnswer = (totalAnswer - 1LL*(size - pos)*MOD_A + MOD_B) % MOD_B;
            currentOrder += size;
        }
        return;
    }
    ++currentOrder;
    totalAnswer = (totalAnswer + ((currentOrder - x) % MOD_A + MOD_A) % MOD_A) % MOD_B;
    for (int digit=0; digit<=9; ++digit) {
        traverse(x*10 + digit);
    }
}

int main() {
    long long n_input;
    cin >> n_input;
    totalCount = n_input;
    generate(0,0);
    currentOrder=0;
    for (int i=0; i<=6; ++i) sort(array[i].begin(), array[i].end());
    for (int i=1; i<=9; ++i) traverse(i);
    cout << totalAnswer;
    return 0;
}
